 foreach(int i in new[]{0,1,2}){var p=new UnityEngine.MaterialPropertyBlock();p.SetVector("_NativeColor",new UnityEngine.Vector4(.2f+i*.2f,.7f,.8f,.7f));wt.GetProperty("Blend",flags).SetValue(world,new[]{"source-over","lighter","screen"}[i]);var matrix=UnityEngine.Matrix4x4.TRS(new UnityEngine.Vector3(50+i*85,70+i*35,0),UnityEngine.Quaternion.Euler(0,0,stage*13),new UnityEngine.Vector3(i==1?-1:1,1,1));Call(world,"DrawNativeMesh",mesh,material,p,(UnityEngine.Matrix4x4?)matrix,(UnityEngine.Color?)new UnityEngine.Color(.8f,.2f,.7f,.65f),7f,true);}
 Call(label,"Draw",world,"ECHO 123 Ж",new UnityEngine.Vector2(160,165),UnityEngine.Color.white);
 Call(world,"End");}
UnityEngine.Color32[] Read(){var t=(UnityEngine.RenderTexture)wt.GetProperty("UiTexture",flags).GetValue(world);var old=UnityEngine.RenderTexture.active;var image=new UnityEngine.Texture2D(t.width,t.height,UnityEngine.TextureFormat.RGBA32,false);try{UnityEngine.RenderTexture.active=t;image.ReadPixels(new UnityEngine.Rect(0,0,t.width,t.height),0,0);return image.GetPixels32();}finally{UnityEngine.RenderTexture.active=old;UnityEngine.Object.Destroy(image);}}
