tick=()=>{try{UnityEditor.EditorApplication.QueuePlayerLoopUpdate();if(!UnityEditor.EditorApplication.isPlaying||UnityEditor.EditorApplication.timeSinceStartup>deadline)throw new System.Exception("Play/deadline");if(last==UnityEngine.Time.frameCount)return;last=UnityEngine.Time.frameCount;if(errors>0)throw new System.Exception("New Unity errors: "+errors);
